package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.equals(double x, double y)
 * Target: Maximize branch and line coverage.
 */
public class MathUtils_equals_TriageGen3Test {

    @Test
    public void testEquals_SameValues() {
        // Test standard positive, negative, and zero values
        assertTrue("Should be true for same positive doubles", MathUtils.equals(1.0, 1.0));
        assertTrue("Should be true for same negative doubles", MathUtils.equals(-5.5, -5.5));
        assertTrue("Should be true for same zero", MathUtils.equals(0.0, 0.0));
        assertTrue("Should be true for same negative zero", MathUtils.equals(-0.0, -0.0));
    }

    @Test
    public void testEquals_DifferentValues() {
        // Test different values
        assertFalse("Should be false for different positive doubles", MathUtils.equals(1.0, 1.1));
        assertFalse("Should be false for different negative doubles", MathUtils.equals(-1.0, -1.1));
        assertFalse("Should be false for mixed signs", MathUtils.equals(1.0, -1.0));
    }

    @Test
    public void testEquals_NaN() {
        // The method logic is: (Double.isNaN(x) && Double.isNaN(y)) || x == y
        // This specifically handles the case where NaN == NaN is traditionally false in IEEE 754
        assertTrue("Should be true when both are NaN", MathUtils.equals(Double.NaN, Double.NaN));

        assertFalse("Should be false when only x is NaN", MathUtils.equals(Double.NaN, 1.0));
        assertFalse("Should be false when only y is NaN", MathUtils.equals(1.0, Double.NaN));
        assertFalse("Should be false when both are NaN but logic fails (sanity check)", !MathUtils.equals(Double.NaN, Double.NaN));
    }

    @Test
    public void testEquals_EdgeCases() {
        // Test Infinity
        assertTrue("Should be true for same positive infinity", MathUtils.equals(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY));
        assertTrue("Should be true for same negative infinity", MathUtils.equals(Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY));
        assertFalse("Should be false for mixed infinities", MathUtils.equals(Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY));

        // Test very small differences (precision)
        double tiny = 1e-300;
        assertTrue("Should be true for very small identical values", MathUtils.equals(tiny, tiny));
        assertFalse("Should be false for slightly different tiny values", MathUtils.equals(tiny, tiny * 2));
    }
}
